import React, {useMemo, useRef, useState, useEffect} from "react";
import axios from "axios";
import WordButton from "./components/WordButton";
import "../styles/English.css";
import Header from "./components/Header";

const English = () => {
	const [data, setData] = useState([]);
	const [loading, setLoading] = useState(true);
	const [error, setError] = useState(null);
	const [answerList, setAnswerList] = useState([]);
	const shuffledList = useMemo(() => shuffleArray(list), [list]);
	const putAnswer = (value) => {
		setAnswerList((prevItem) => {
			const newItem = prevItem.includes(value)
				? prevItem.filter((i) => i !== value) // 제거
				: [...prevItem, value]; // 추가

			return newItem;
		});
	};

	useEffect(() => {
		// 데이터 요청
		const fetchData = async () => {
			try {
				const response = await axios.get(
					"http://localhost:8080/api/v1/eng/1"
				);
				setData(response.data); // 서버에서 받은 데이터 저장
				setLoading(false);
			} catch (err) {
				setError(err.message);
				setLoading(false);
			}
		};

		fetchData();
	}, []);

	if (loading) return <p>Loading...</p>;
	if (error) return <p>Error: {error}</p>;
	return (
		<div className="quiz-container">
			<div className="quiz-sentence">
				<p>{data.korSen}</p>
				{Object.values(data.engSenList)
					.sort(() => randomNumber)
					.map((value, key) => (
						<WordButton
							size="large"
							key={key}
							label={value}
							onClick={() => putAnswer(value)}
						/>
					))}
				{console.log(answerList)}
				<p>{answerList.map((value, index) => value + " ")}</p>
			</div>
		</div>
	);
};
export default English;
